import { registerSW } from 'virtual:pwa-register';

/**
 * Registers the Workbox service worker generated by vite-plugin-pwa (the replacement for
 * Angular's `ServiceWorkerModule.register('ngsw-worker.js')`). With `registerType: 'autoUpdate'`
 * a new build takes over on the next navigation without user interaction.
 *
 * In `vite dev` the virtual module is a no-op because `devOptions.enabled` is false.
 */
export function registerServiceWorker(): void {
    if (typeof navigator === 'undefined' || !('serviceWorker' in navigator)) {
        return;
    }

    registerSW({
        immediate: true,
        onOfflineReady() {
            console.info('[pwa] app shell cached, ready to work offline');
        },
        onRegisterError(error: unknown) {
            console.error('[pwa] service worker registration failed', error);
        },
    });
}
